<template>
 <section class="import-review" aria-label="Revisión de importación">
  <h3>{{ tr('Revisar y corregir miembros','Review and correct members') }}</h3>
  <p>{{ tr('Importa las filas completas ahora. Para las demás, elige si autorizas los datos faltantes o prefieres completarlos después.','Import complete rows now. For the rest, choose whether to authorize missing information or complete it later.') }}</p>
  <div class="review-summary">
   <div><strong>{{ rows.length - invalidCount }}</strong><span>{{ tr('Completas','Complete') }}</span><small>{{ tr('Sin errores de datos.','Without data errors.') }}</small></div>
   <div><strong>{{ authorizedCount }}</strong><span>{{ tr('Autorizadas por ti','Authorized by you') }}</span><small>{{ tr('Se importarán con una marca de datos faltantes.','Will be imported with a missing-data label.') }}</small></div>
   <div><strong>{{ rows.length - eligibleCount }}</strong><span>{{ tr('Por completar','Needs attention') }}</span><small>{{ tr('Puedes corregirlas aquí o guardarlas para después.','Correct them here or save them for later.') }}</small></div>
   <button type="button" class="summary-filter" :class="{'summary-filter--active':onlyDuplicates}" :aria-pressed="onlyDuplicates" @click="toggleDuplicates"><strong>{{ duplicateCount }}</strong><span>{{ tr('Duplicados detectados','Duplicates detected') }}</span><small>{{ onlyDuplicates ? tr('Mostrar todas las filas','Show all rows') : tr('Ver solo posibles duplicados','Show possible duplicates only') }}</small></button>
  </div>
  <p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p>
  <p v-if="savedAt" class="save-status" role="status">{{ savedCount }} {{ tr('filas guardadas en este borrador. Guarda de nuevo para conservar solo las pendientes.','rows saved in this draft. Save again to keep only pending rows.') }}</p>
  <p v-if="dirty" class="alert alert-warning" role="status">{{ tr('Revisa tus cambios antes de importar. Los conteos se actualizarán al validar.','Validate your changes before importing. Counts will update after validation.') }}</p>
  <p v-if="duplicateCount" class="alert alert-info">{{ duplicateCount }} {{ tr('posibles miembros existentes. Se omiten por defecto; abre cada fila para elegir actualizar.','possible existing members. They are skipped by default; open each row to choose an update.') }}</p>
  <div class="member-import-actions">
   <div><button type="button" class="btn btn-primary" :disabled="busy||dirty||!eligibleCount" @click="commit">{{ duplicateCount ? tr('Procesar filas listas','Process ready rows') : authorizedCount ? tr('Importar completas y autorizadas','Import complete and authorized rows') : tr('Importar solo completas','Import complete rows only') }} ({{ eligibleCount }})</button><small>{{ tr('Se importan los nuevos, se aplican las actualizaciones elegidas y se omiten los duplicados marcados. Las filas pendientes se guardan para después.','New members are imported, selected updates applied, and marked duplicates skipped. Pending rows are saved for later.') }}</small></div>
   <div><button type="button" class="btn btn-outline-secondary" :disabled="busy" @click="validate">{{ tr('Guardar pendientes para después','Save pending rows for later') }}</button><small>{{ tr('No importa miembros. Guarda solo filas con errores o datos faltantes.','Does not import members. Saves only rows with errors or missing information.') }}</small></div>
  </div>
  <div class="review-toolbar"><label><input type="checkbox" v-model="onlyErrors" @change="page=1" /> {{ tr('Mostrar solo filas por revisar','Show only rows needing review') }}</label><button v-if="dirty" type="button" class="btn btn-outline-primary" :disabled="busy" @click="validate">{{ tr('Validar correcciones','Validate corrections') }}</button></div>
  <p class="authorization-help">{{ tr('¿Te falta información? Marca “Importar con datos faltantes” en cada fila que quieras autorizar. Los valores inválidos deben corregirse.','Missing information? Select “Import with missing information” on each row you want to authorize. Invalid values must be corrected.') }}</p>
  <fieldset :disabled="busy">
   <div class="review-rows">
    <article v-for="row in pageRows" :key="row.line" class="review-row" :class="{'invalid-row':Object.keys(row.errors).length,'duplicate-row':isDuplicate(row)}">
     <header class="review-row-heading"><strong>{{ tr('Fila','Row') }} {{ row.line }} · {{ [row.values.FirstName,row.values.LastName].filter(Boolean).join(' ') || tr('Sin nombre','Missing name') }}</strong><span v-if="isDuplicate(row)" class="duplicate-badge">{{ tr('Posible duplicado','Possible duplicate') }}</span><span v-if="Object.keys(row.errors).length" class="error-badge">{{ tr('Requiere revisión','Needs review') }}</span></header>
     <div v-if="row.duplicate_matches?.length" class="duplicate-choice"><strong>{{ tr('Posible miembro existente','Possible existing member') }}</strong><p v-for="match in row.duplicate_matches" :key="match.id">{{ match.name }} · {{ match.dob || '—' }} · #{{ match.id }} ({{ match.match==='person_id'?'PersonId':tr('nombre y nacimiento','name and birth date') }})</p><div class="duplicate-controls"><label>{{ tr('Acción','Action') }}<select v-model="row.duplicate_action" class="form-select" @change="duplicateChanged(row)"><option value="skip">{{ tr('Omitir','Skip') }}</option><option value="update">{{ tr('Actualizar miembro existente','Update existing member') }}</option></select></label><label v-if="row.duplicate_action==='update'">{{ tr('Miembro a actualizar','Member to update') }}<select v-model.number="row.duplicate_target" class="form-select" @change="dirty=true"><option :value="null">{{ tr('Seleccionar','Select') }}</option><option v-for="match in row.duplicate_matches" :key="match.id" :value="match.id">{{ match.name }} · #{{ match.id }}</option></select></label></div></div>
     <p v-if="row.duplicate_file_lines?.length" class="duplicate-file">{{ tr('El mismo PersonId también aparece en las filas','The same PersonId also appears in rows') }} {{ row.duplicate_file_lines.join(', ') }}.</p>
     <label v-if="row.can_authorize" class="row-authorization"><input type="checkbox" v-model="row.authorize_missing" /> {{ tr('Importar con datos faltantes','Import with missing information') }}: {{ row.missing_fields.map(missingLabel).join(', ') }}</label><small v-else-if="Object.keys(row.errors).length" class="field-error">{{ tr('Corrige los valores inválidos; no se pueden autorizar.','Correct invalid values; they cannot be authorized.') }}</small>
     <div class="review-fields"><label v-for="key in core" :key="key">{{ label(key) }}<input v-model="row.values[key]" class="form-control" :class="{'is-invalid':row.errors[key]}" :aria-invalid="!!row.errors[key]" :aria-label="`${label(key)} · ${row.line}`" @input="changed(row)" /><small v-for="msg in row.errors[key]" :key="msg" class="field-error">{{ msg }}</small></label></div>
     <details class="extra-fields"><summary>{{ tr('Ver / editar otros datos','View / edit other information') }} <span v-if="hasExtraErrors(row)" class="field-error">{{ tr('· Hay datos que revisar','· Contains fields to review') }}</span></summary><div class="review-fields"><label v-for="key in extraHeaders" :key="key">{{ key }}<input v-model="row.values[key]" class="form-control" :class="{'is-invalid':row.errors[key]}" :aria-invalid="!!row.errors[key]" :aria-label="`${key} · ${row.line}`" @input="changed(row)" /><small v-for="msg in row.errors[key]" :key="msg" class="field-error">{{ msg }}</small></label></div></details>
    </article>
   </div>
  </fieldset>
  <p v-if="!filtered.length">{{ tr('No hay filas para este filtro.','No rows match this filter.') }}</p>
  <nav class="review-toolbar" :aria-label="tr('Páginas de importación','Import pages')"><button class="btn btn-outline-secondary" :disabled="page<=1||busy" @click="page--">{{ tr('Anterior','Previous') }}</button><span>{{ page }} / {{ pages }}</span><button class="btn btn-outline-secondary" :disabled="page>=pages||busy" @click="page++">{{ tr('Siguiente','Next') }}</button></nav>
 </section>
</template>
<script setup>
import {ref,computed,watch} from 'vue'
import {membersApi} from '../services/membersApi'
import {useUiStore} from '../stores/uiStore'
const props=defineProps({review:{type:Object,required:true}}),emit=defineEmits(['imported','busy','saved'])
const ui=useUiStore(),tr=(es,en)=>ui.locale==='es'?es:en
const rows=ref([]),headers=ref([]),valid=ref(false),dirty=ref(false),busy=ref(false),error=ref(''),page=ref(1),onlyErrors=ref(false),onlyDuplicates=ref(false),draftId=ref(null),revision=ref(null),savedAt=ref(null),savedCount=ref(0)
const missingLabel=key=>({name:tr('nombre','name'),email:tr('correo','email'),phone:tr('teléfono','phone'),dob:tr('nacimiento','birth date')})[key]||key
const isDuplicate=row=>Boolean(row.duplicate_matches?.length||row.duplicate_file_lines?.length)
const duplicateCount=computed(()=>rows.value.filter(isDuplicate).length)
const eligibleCount=computed(()=>rows.value.filter(r=>r.duplicate_matches?.length&&r.duplicate_action==='skip'||!Object.keys(r.errors).length||(r.can_authorize&&r.authorize_missing)).length)
const authorizedCount=computed(()=>rows.value.filter(r=>Object.keys(r.errors).length&&r.can_authorize&&r.authorize_missing).length)
const core=['FirstName','LastName','Email','MobilePhone','FamilyPhone','WorkPhone','BornOn']
const labels={FirstName:['Nombre *','Name *'],LastName:['Apellido','Surname'],Email:['Correo *','Email *'],MobilePhone:['Móvil','Mobile'],FamilyPhone:['Familiar','Family'],WorkPhone:['Trabajo','Work'],BornOn:['Nacimiento *','Birth date *']}
const label=key=>tr(...labels[key])
const extraHeaders=computed(()=>headers.value.filter(k=>!core.includes(k)))
const invalidCount=computed(()=>rows.value.filter(r=>Object.keys(r.errors).length).length)
const filtered=computed(()=>rows.value.filter(r=>(!onlyDuplicates.value||isDuplicate(r))&&(!onlyErrors.value||Object.keys(r.errors).length||isDuplicate(r))))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10)))
const pageRows=computed(()=>filtered.value.slice((page.value-1)*10,page.value*10))
const hasExtraErrors=row=>extraHeaders.value.some(key=>row.errors[key])
function apply(data){draftId.value=data.draft_id??null;revision.value=data.revision??null;savedAt.value=data.updated_at??null;savedCount.value=data.saved_count??data.count??0;rows.value=data.rows;headers.value=data.headers;valid.value=data.valid;dirty.value=false;page.value=Math.min(page.value,pages.value)}
watch(()=>props.review,data=>{page.value=1;onlyErrors.value=false;onlyDuplicates.value=false;apply(JSON.parse(JSON.stringify(data)))},{immediate:true})
function toggleDuplicates(){onlyDuplicates.value=!onlyDuplicates.value;onlyErrors.value=false;page.value=1}
function changed(row){row.authorize_missing=false;row.duplicate_action='skip';row.duplicate_target=null;dirty.value=true;valid.value=false}
function duplicateChanged(row){row.duplicate_target=row.duplicate_action==='update'&&row.duplicate_matches.length===1?row.duplicate_matches[0].id:null;dirty.value=true}
const message=e=>Object.entries(e.response?.data?.errors||{}).map(([k,v])=>`${k}: ${v.join(' ')}`).join('\n')||tr('No se pudo completar la operación. Tus cambios siguen en la tabla.','Unable to complete the operation. Your edits remain in the table.')
function working(value){busy.value=value;emit('busy',value)}
async function persist(pendingOnly=true){const data=await membersApi.saveDraft(draftId.value,{revision:revision.value,pending_only:pendingOnly,rows:rows.value.map(r=>({line:r.line,values:r.values,authorize_missing:r.authorize_missing||false,duplicate_action:r.duplicate_action==='update'?'update':'skip',duplicate_target:r.duplicate_target||null}))});apply(data);emit('saved',draftId.value)}
async function validate(){working(true);error.value='';try{await persist()}catch(e){error.value=message(e);valid.value=false;dirty.value=true}finally{working(false)}}
async function commit(){if(dirty.value||!eligibleCount.value)return;working(true);error.value='';try{await persist(false);const result=await membersApi.commitDraft(draftId.value,revision.value);apply(result.review);emit('imported',result)}catch(e){error.value=message(e);dirty.value=true}finally{working(false)}}
</script>
<style scoped>
.review-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:18px 0}.review-summary>div{padding:14px;border:1px solid #dce5df;border-radius:10px;background:#f7faf8;display:grid;gap:4px}.review-summary strong{font-size:1.25rem;color:#215c4e}.review-summary span{font-weight:600}.review-summary small,.member-import-actions small{color:#52645a;line-height:1.5}.member-import-actions{display:flex;gap:20px;flex-wrap:wrap;margin:20px 0}.member-import-actions>div{display:flex;flex-direction:column;align-items:flex-start;gap:7px;flex:1 1 260px}.member-import-actions button{white-space:normal;text-align:left}.authorization-help{font-size:.8125rem;color:#52645a}.save-status{padding:10px 12px;border-left:3px solid #28705b;background:#f1f8f4;font-size:.8125rem}@media(max-width:600px){.review-summary{grid-template-columns:1fr;gap:8px}.review-summary>div{grid-template-columns:36px 1fr;padding:10px}.review-summary small{grid-column:2}.member-import-actions{gap:14px}.member-import-actions>div{flex-basis:100%}.member-import-actions button{width:100%}}

.import-review{margin-top:24px;border-top:1px solid #dce5df;padding-top:20px;min-width:0}.review-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:16px 0}.review-toolbar label{display:flex;align-items:center;gap:8px}.review-table{width:100%;table-layout:fixed;font-size:.8125rem}.review-table th{font-weight:500;text-align:left;padding:10px}.review-table td{vertical-align:top;padding:12px 10px;border-top:1px solid #dce5df;overflow-wrap:anywhere}.review-table label{display:block;margin:8px 0}.review-table input{font-size:.8125rem;min-width:0;width:100%}.review-table summary{cursor:pointer}.invalid-row{background:#fffaf6}.row-authorization{border:1px solid #d5a349;padding:8px;border-radius:6px;background:#fff6df}.row-authorization input[type="checkbox"]{width:16px;height:16px;display:inline-block;margin-right:6px}.field-error{display:block;color:#a42b27;margin-top:4px}.date-hint{font-size:.65rem;color:#52645a}.alert{white-space:pre-wrap;overflow-wrap:anywhere}fieldset{min-width:0}@media(max-width:850px){.review-table thead{display:none}.review-table tr{display:block;border:1px solid #dce5df;border-radius:8px;margin:12px 0;padding:10px}.review-table td{display:block;border:0;padding:0 4px}.review-table{display:block}.review-table tbody{display:block}.review-toolbar .btn{max-width:100%}}
</style>
<style scoped>
.review-summary{grid-template-columns:repeat(4,minmax(0,1fr))}.review-summary .summary-filter{display:grid;gap:4px;text-align:left;padding:14px;border:1px solid #c6a860;border-radius:10px;background:#fffaf0;color:#58461f;width:100%;font-size:inherit}.summary-filter strong{font-size:1.25rem;color:#805c16}.summary-filter span{font-weight:600}.summary-filter small{color:#6d6044;line-height:1.5}.summary-filter:hover,.summary-filter--active{background:#fff0c9!important;border-color:#9e711c!important}.summary-filter:focus-visible{outline:3px solid #1f6f5c;outline-offset:2px}.review-rows{display:grid;gap:14px}.review-row{min-width:0;padding:16px;border:1px solid #dce5df;border-radius:10px;background:#fff}.review-row.invalid-row{background:#fffaf6}.review-row.duplicate-row{border-color:#ddbf80}.review-row-heading{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.review-row-heading strong{margin-right:auto;overflow-wrap:anywhere}.duplicate-badge,.error-badge{padding:4px 8px;border-radius:99px;font-size:11px;background:#fff0c9;color:#79550e}.error-badge{background:#ffebea;color:#923b35}.review-fields,.duplicate-controls{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.review-fields label,.duplicate-controls label{display:grid;align-content:start;gap:5px;min-width:0;font-size:12px;color:#52645a}.review-fields input,.duplicate-controls select{width:100%;min-width:0;font-size:13px}.duplicate-choice{padding:12px;border-radius:8px;background:#fff8e9;margin:0 0 12px}.duplicate-choice p,.duplicate-file{font-size:12px;margin:5px 0;color:#705924}.duplicate-controls{grid-template-columns:repeat(2,minmax(0,1fr));margin-top:8px}.extra-fields{margin-top:14px;border-top:1px solid #e6ece8;padding-top:12px}.extra-fields summary{cursor:pointer;color:#21664f;font-weight:600}.extra-fields .review-fields{margin-top:12px}.field-error{display:block;color:#a42b27;margin-top:4px}.extra-fields summary .field-error{display:inline}.row-authorization{display:block;margin:10px 0}.row-authorization input{width:16px;height:16px}@media(max-width:1000px){.review-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.review-fields{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.review-summary,.review-fields,.duplicate-controls{grid-template-columns:1fr}.review-summary .summary-filter{grid-template-columns:36px 1fr;padding:10px}.summary-filter small{grid-column:2}.review-row{padding:12px}}
</style>
